#!/usr/bin/env python3
"""Street Legends frontend: Radio house item (Appliances tab) + house-level audio.

PRICE = 5000 (buy), SELL = 2500 (generic half-refund remove endpoint).
User spec (2026-11-03): Radio in the Appliances tab; tap the radio inside
the house to play his Hush Music Radio stream, tap again to stop; audio
lives at HOUSE-INTERIOR level (NOT inside any game modal) so opening a
house game (Pool, Scrabble, etc.) does NOT stop it; leaving the house
(LEAVE HOUSE / interior close) stops it automatically; selling the radio
while it plays stops it too.

STREAM: direct MP3 https://streaming.live365.com/a30094 (NOT an embed).
Plain audio URL, already proven in his Roku / Fire TV builds.

AUDIO PATH (decided at run time from frontend/package.json — never a
static import for a library that may not be installed):
- If "expo-audio" is listed: expo-audio path, the app's own pattern
  (hooks/useSoundEffects.ts uses createAudioPlayer({ uri }) from
  'expo-audio'). Player is held in a ref owned by the interior
  component; game modals never touch it.
- Else if "react-native-webview" is listed: hidden-WebView path — a 1x1
  WebView with an <audio autoplay> element, rendered only while
  radioPlaying is true (unmounting stops the audio). Same state flag,
  same leave/sell stop.
- Else: WARNING, audio wiring is skipped (menu entry + image still land;
  tap does nothing until audio is wired). The patch never writes code
  that references a missing library.

LEAVE-HOUSE STOP (two mechanisms, either suffices):
1. useEffect on interiorHouse: when the interior house becomes falsy
   (house closed), stopRadio() runs (no-op when not playing).
2. (expo path only) RadioStopOnUnmount rendered as a sibling just before
   the LEAVE HOUSE button JSX: when the interior modal unmounts, its
   cleanup stops the player. If the LEAVE HOUSE JSX anchor is not
   matched, a WARNING prints and mechanism 1 still covers the
   interiorHouse-driven close path.
Game modals open on top of the interior without clearing interiorHouse
and without unmounting the interior modal, so neither mechanism fires
while a house game is open — the music keeps playing.

IMAGE: frontend/assets/houses/items/radio.png is written from the
embedded base64 cutout (boombox with the black background removed —
house items must be cutouts, never a black square). If the file already
holds the same bytes, SKIP.

SECTIONS (each scoped; a missed anchor prints WARNING and the patch
continues; re-running prints SKIP, never duplicates):
- image write, appliances entry, imports (gated: audio block is only
  inserted when its required imports actually land), radio state +
  stop/toggle/sell + leave effect, stop-on-unmount render (expo path),
  WebView render (webview path), itemId tap routing, placed-radio guard
  in handleHouseItemToggle (component scope only).
- "Already present" checks are scoped to the component being wired
  (never a global check — global checks twice falsely skipped the pool
  and dartboard buttons).

Run from /app: python3 frontend/patch-house-radio-frontend.py
Frontend only: reload Expo Go after running, no build, no Deploy for
this patch itself (the backend catalog patch needs Publish separately).
"""
import base64
import re
import sys
from pathlib import Path

INDEX = Path("frontend/app/(tabs)/index.tsx")
PKG = Path("frontend/package.json")
PNG = Path("frontend/assets/houses/items/radio.png")
MARKER = "RADIO_FRONTEND_OK"
PRICE = 5000
STREAM_URL = "https://streaming.live365.com/a30094"
RADIO_PNG_B64 = ""
MAP_ANCHOR = "export default function MapScreen() {"
MODAL_ANCHOR = "      {/* House Interior Modal */}"
ENTRY = "{ id: 'radio', name: 'Radio', image: require('../../assets/houses/items/radio.png'), price: %d }" % PRICE


def import_after_last(src, line):
    lines = src.split("\n")
    last = -1
    for i, ln in enumerate(lines[:80]):
        if ln.strip().startswith("import "):
            last = i
    if last < 0:
        return src, False
    lines.insert(last + 1, line)
    return "\n".join(lines), True


def add_to_import(src, module, names):
    """Add names to a single-line `import {...} from 'module'`. Returns (src, ok)."""
    m = re.search(r"import\s+(?:\w+\s*,\s*)?\{([^}]*)\}\s*from\s*['\"]" + re.escape(module) + r"['\"]", src)
    if not m:
        return src, False
    have = [x.strip() for x in m.group(1).split(",") if x.strip()]
    missing = [n for n in names if n not in have]
    if not missing:
        return src, True
    new_inner = ", ".join(have + missing)
    src = src[:m.start(1)] + " " + new_inner + " " + src[m.end(1):]
    return src, True


def main():
    try:
        src = INDEX.read_text(encoding="utf-8")
    except FileNotFoundError:
        print("RADIO_FRONTEND_ERROR: frontend/app/(tabs)/index.tsx not found (run from /app)")
        return 1
    orig = src

    # 0. Image (cutout PNG, embedded base64).
    try:
        png_bytes = base64.b64decode(RADIO_PNG_B64)
    except Exception as e:
        print("WARNING: radio PNG base64 invalid (%s) - image not written" % e)
        png_bytes = b""
    if png_bytes:
        if PNG.exists() and PNG.read_bytes() == png_bytes:
            print("SKIP: radio.png already present")
        else:
            PNG.parent.mkdir(parents=True, exist_ok=True)
            PNG.write_bytes(png_bytes)
            print("OK: radio.png written (%d bytes)" % len(png_bytes))

    # 1. Audio path from live package.json (never guess).
    audio_path = "none"
    try:
        pkg = PKG.read_text(encoding="utf-8")
        if '"expo-audio"' in pkg:
            audio_path = "expo"
        elif "react-native-webview" in pkg:
            audio_path = "webview"
    except FileNotFoundError:
        print("WARNING: frontend/package.json not found - audio path unknown")
    print("AUDIO_PATH: %s" % audio_path)
    if audio_path == "none":
        print("WARNING: neither expo-audio nor react-native-webview in package.json - audio wiring SKIPPED (entry + image still land)")

    # 2. HOUSE_ITEMS appliances entry (scoped to the HOUSE_ITEMS block).
    if ENTRY in src:
        print("SKIP: Radio already in Appliances list")
    else:
        hpos = src.find("HOUSE_ITEMS")
        ok = False
        if hpos >= 0:
            apos = src.find("appliances:", hpos)
            if apos >= 0:
                bstart = src.find("[", apos)
                if bstart >= 0:
                    depth = 0
                    bend = -1
                    for i in range(bstart, min(len(src), bstart + 8000)):
                        c = src[i]
                        if c == "[":
                            depth += 1
                        elif c == "]":
                            depth -= 1
                            if depth == 0:
                                bend = i
                                break
                    if bend > bstart:
                        inner = src[bstart + 1:bend]
                        if inner.strip() == "":
                            src = src[:bend] + ENTRY + src[bend:]
                        else:
                            src = src[:bend] + ", " + ENTRY + src[bend:]
                        print("OK: Radio added to Appliances list")
                        ok = True
        if not ok:
            print("WARNING: HOUSE_ITEMS appliances array anchor not matched - Radio not added to menu")

    # 3. Imports + audio block (gated: only insert code whose imports landed).
    audio_ok = False
    if audio_path != "none" and "toggleRadio" not in src:
        if MAP_ANCHOR not in src:
            print("WARNING: MapScreen anchor not found - audio block not added")
        else:
            work = src
            imp_ok = True
            work, ok = add_to_import(work, "react", ["useState", "useRef", "useCallback", "useEffect"])
            if not ok:
                print("WARNING: could not extend react import (useState/useRef/useCallback/useEffect)")
                imp_ok = False
            work, ok = add_to_import(work, "react-native", ["Alert"])
            if not ok:
                print("WARNING: could not extend react-native import (Alert)")
                imp_ok = False
            if audio_path == "expo":
                if "from 'expo-audio'" in work or 'from "expo-audio"' in work:
                    print("SKIP: expo-audio import already present")
                else:
                    work, ok = import_after_last(work, "import { createAudioPlayer } from 'expo-audio';")
                    if not ok or "createAudioPlayer" not in work:
                        print("WARNING: could not add expo-audio import")
                        imp_ok = False
                    else:
                        print("OK: expo-audio import added")
            else:
                if "react-native-webview" in work:
                    print("SKIP: react-native-webview import already present")
                else:
                    work, ok = import_after_last(work, "import { WebView } from 'react-native-webview';")
                    if not ok or "WebView" not in work:
                        print("WARNING: could not add react-native-webview import")
                        imp_ok = False
                    else:
                        print("OK: react-native-webview import added")
            if imp_ok:
                if audio_path == "expo":
                    module_block = """
const RADIO_STREAM_URL = '%s';

// RADIO_AUDIO: house-level radio controller. Rendered inside the house
// interior only; unmounting stops the player (LEAVE HOUSE safety net).
const RadioStopOnUnmount = ({ onStop }: { onStop: () => void }) => {
  useEffect(() => {
    return () => { onStop(); };
  }, []);
  return null;
};
""" % STREAM_URL
                    if "RADIO_STREAM_URL" not in work:
                        work = work.replace(MAP_ANCHOR, module_block.strip("\n") + "\n\n" + MAP_ANCHOR, 1)
                        print("OK: radio stream const + stop-on-unmount component added")
                    state_block = """
  // RADIO_AUDIO (house-level): owned by the interior, NOT by any game
  // modal, so opening a house game never stops it. LEAVE HOUSE stops it
  // via the interiorHouse effect below + RadioStopOnUnmount cleanup.
  const [radioPlaying, setRadioPlaying] = useState(false);
  const radioPlayerRef = useRef<any>(null);
  const stopRadio = useCallback(() => {
    try { radioPlayerRef.current?.pause(); } catch {}
    try { radioPlayerRef.current?.release(); } catch {}
    radioPlayerRef.current = null;
    setRadioPlaying(false);
  }, []);
  const toggleRadio = useCallback(async () => {
    if (radioPlayerRef.current) { stopRadio(); return; }
    try {
      const player = createAudioPlayer({ uri: RADIO_STREAM_URL });
      player.volume = 0.8;
      radioPlayerRef.current = player;
      player.play();
      setRadioPlaying(true);
    } catch (e) {
      Alert.alert('Radio', 'Could not start the station. Try again.');
    }
  }, [stopRadio]);
  const sellRadio = async () => {
    stopRadio();
    if (!interiorHouse || !playerId) return;
    try {
      const res = await removeHouseItem(interiorHouse.id, playerId, 'radio');
      if (res?.house) {
        setInteriorHouse(res.house);
      } else {
        setInteriorHouse({ ...interiorHouse, items: (interiorHouse.items || []).filter((it: any) => it.item_id !== 'radio') });
      }
      if (res && typeof res.cash === 'number' && player) setPlayer({ ...player, cash: res.cash });
    } catch (e: any) {
      Alert.alert('Could not sell', e?.message || 'Try again.');
    }
  };
  useEffect(() => {
    if (!interiorHouse) { stopRadio(); }
  }, [interiorHouse, stopRadio]);
"""
                else:
                    state_block = """
  // RADIO_AUDIO (house-level, WebView path): the hidden WebView renders
  // only while radioPlaying is true, so leaving the house (which clears
  // radioPlaying via the effect below) unmounts it and stops the audio.
  // Game modals never touch this flag, so house games keep playing.
  const [radioPlaying, setRadioPlaying] = useState(false);
  const stopRadio = useCallback(() => { setRadioPlaying(false); }, []);
  const toggleRadio = useCallback(() => { setRadioPlaying((p: boolean) => !p); }, []);
  const sellRadio = async () => {
    stopRadio();
    if (!interiorHouse || !playerId) return;
    try {
      const res = await removeHouseItem(interiorHouse.id, playerId, 'radio');
      if (res?.house) {
        setInteriorHouse(res.house);
      } else {
        setInteriorHouse({ ...interiorHouse, items: (interiorHouse.items || []).filter((it: any) => it.item_id !== 'radio') });
      }
      if (res && typeof res.cash === 'number' && player) setPlayer({ ...player, cash: res.cash });
    } catch (e: any) {
      Alert.alert('Could not sell', e?.message || 'Try again.');
    }
  };
  useEffect(() => {
    if (!interiorHouse && radioPlaying) { setRadioPlaying(false); }
  }, [interiorHouse, radioPlaying]);
"""
                work = work.replace(MAP_ANCHOR, MAP_ANCHOR + state_block.rstrip("\n"), 1)
                src = work
                audio_ok = True
                print("OK: radio state + stop/toggle/sell + leave effect added (%s path)" % audio_path)
            else:
                print("WARNING: audio block skipped (imports missing) - code would reference missing imports")
    elif "toggleRadio" in src:
        print("SKIP: radio audio already present")
        audio_ok = True

    # 4a. Expo path: stop-on-unmount render just before the LEAVE HOUSE button.
    if audio_path == "expo" and audio_ok and "RadioStopOnUnmount onStop" not in src:
        lines = src.split("\n")
        # The real button is a <Text>LEAVE HOUSE</Text> line; ignore comment
        # mentions of LEAVE HOUSE (the patch's own comments contain it).
        cands = [i for i, ln in enumerate(lines) if "LEAVE HOUSE" in ln]
        text_cands = [i for i in cands if "<Text" in lines[i]]
        leave_idx = text_cands[0] if text_cands else (cands[-1] if cands else -1)
        placed = False
        if leave_idx >= 0:
            for j in range(leave_idx, max(-1, leave_idx - 8), -1):
                if "TouchableOpacity" in lines[j]:
                    indent = lines[j][:len(lines[j]) - len(lines[j].lstrip())]
                    lines.insert(j, indent + "{radioPlaying ? (<RadioStopOnUnmount onStop={stopRadio} />) : null}")
                    src = "\n".join(lines)
                    placed = True
                    print("OK: stop-on-unmount render added before LEAVE HOUSE button")
                    break
        if not placed:
            print("WARNING: LEAVE HOUSE button anchor not matched - stop-on-unmount render not added (interiorHouse effect still stops on close)")
    elif audio_path == "expo" and "RadioStopOnUnmount onStop" in src:
        print("SKIP: stop-on-unmount render already present")

    # 4b. WebView path: hidden audio WebView rendered while playing.
    if audio_path == "webview" and audio_ok:
        wv = "{radioPlaying ? (<WebView source={{ html: '<html><body style=\"margin:0;background:#000\"><audio autoplay src=\"" + STREAM_URL + "\"></audio></body></html>' }} mediaPlaybackRequiresUserAction={false} javaScriptEnabled={true} style={{ width: 1, height: 1, opacity: 0 }} />) : null}"
        if "radioPlaying ? (<WebView" in src:
            print("SKIP: radio WebView render already present")
        elif MODAL_ANCHOR in src:
            src = src.replace(MODAL_ANCHOR, wv + "\n" + MODAL_ANCHOR, 1)
            print("OK: hidden radio WebView render added")
        else:
            print("WARNING: House Interior Modal anchor not found - WebView render not added")

    # 5. ItemId tap routing: tapping the placed radio toggles it (same router games use).
    if "=== 'radio') toggleRadio" in src or '=== "radio") toggleRadio' in src:
        print("SKIP: radio tap already wired")
    elif audio_ok:
        tap_pat = re.compile(
            r"^([ \t]*)if\s*\(\s*(\w+)\s*===\s*'(scrabble|texas_holdem|dominoes|cardtable|dartboard|pool-table|chess_checkers)'\s*\)\s*set\w+MenuOpen\(true\);",
            re.M,
        )
        m = tap_pat.search(src)
        if m:
            indent, var = m.group(1), m.group(2)
            src = src[:m.end()] + "\n" + indent + "if (%s === 'radio') toggleRadio();" % var + src[m.end():]
            print("OK: radio tap wired (after %s router line)" % m.group(3))
        else:
            print("WARNING: item tap router anchor not found - radio tap not wired")

    # 6. Placed-radio guard in handleHouseItemToggle (component scope only).
    if "toggleRadio(); return; }" in src and "id === 'radio'" in src:
        print("SKIP: handleHouseItemToggle radio guard already present")
    elif audio_ok:
        mappos = src.find(MAP_ANCHOR)
        hpos = src.find("handleHouseItemToggle")
        done = False
        if mappos >= 0 and hpos > mappos:
            dm = re.search(r"handleHouseItemToggle\s*=\s*(?:async\s*)?\(\s*(\w+)", src[hpos:])
            if dm:
                param = dm.group(1)
                bpos = src.find("{", hpos + dm.end())
                if bpos >= 0 and bpos - hpos < 200:
                    indent = "      "
                    guard = "\n" + indent + "if (%s?.id === 'radio' && (interiorHouse?.items || []).some((it: any) => it.item_id === 'radio')) { toggleRadio(); return; }" % param
                    src = src[:bpos + 1] + guard + src[bpos + 1:]
                    print("OK: placed-radio guard added to handleHouseItemToggle")
                    done = True
        if not done:
            print("WARNING: handleHouseItemToggle anchor not matched - menu-row guard not added (item tap router may still cover it)")

    if src != orig:
        INDEX.write_text(src, encoding="utf-8")
        print("OK: index.tsx updated")
    else:
        print("SKIP: index.tsx unchanged")
    print(MARKER)
    return 0


if __name__ == "__main__":
    sys.exit(main())
